// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {BANK_SAFE} from "../src/BANK_SAFE.sol";

contract InvMutTest is Test {
    BANK_SAFE c;
    function setUp() public { c = new BANK_SAFE(); }
    function testFuzz_property(uint256 initialMin, uint256 newMin, address caller) public {
        vm.assume(caller != address(0));

        c.SetMinSum(initialMin);
        c.Initialized();
        vm.prank(caller);
        bool ok;
        try c.SetMinSum(newMin) {
            ok = true;
        } catch {
            ok = false;
        }

        assertTrue(c.MinSum() == initialMin);
    }
}
